setup.test_reverse.py:
from reverse import reverse


def test_reverse_a_word():
    assert reverse("hello") == "olleh"


def test_reverse_keeps_spaces():
    assert reverse("a b c") == "c b a"


def test_reverse_edge_cases():
    assert reverse("") == ""
    assert reverse("x") == "x"
    assert reverse("aba") == "aba"
